class Agenthub < Formula
  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.12.3"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.3/agenthub-0.12.3-a03a808-darwin-arm64.tar.gz"
      sha256 "b420740c18dbf0e0f9c7ac1f64cfe60f3fc838b54b8d403737939f37fed52bf0"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.3/agenthub-0.12.3-a03a808-darwin-amd64.tar.gz"
      sha256 "506424d5f034d3ad832fb3be1ff11ae1981fbc42d55d8d7c6a781d474ebd02c2"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.3/agenthub-0.12.3-a03a808-linux-arm64.tar.gz"
      sha256 "77fde1d94883576331eddde1b62b1e5ccf0ff1a5dee476cd1f5660c069e437bf"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.3/agenthub-0.12.3-a03a808-linux-amd64.tar.gz"
      sha256 "9831b130a10c955fc4ee89a766c26d48b66bcc730526448b73288e51ff391bc0"
    end
